  3	import { useRef, useState, useTransition } from "react";
  4	import { Icon } from "@/components/nx/Icon";
  5	import { captureSiteThumb, clearSiteThumb, type SiteThumbView } from "@/lib/actions-hosting-sites";
  6	
  7	/**
  8	 * The picture of a customer's website.
  9	 *
 10	 * THE ONE RULE THIS COMPONENT EXISTS TO ENFORCE: the card always says which of
 11	 * three things it is showing, and it never shows a fourth.
 12	 *
 13	 *   1. CAPTURE — a real screenshot of the live hostname, taken by the worker
 14	 *      with headless Chromium (lib/hosting-thumb.ts). Badged "Live capture".
 15	 *   2. UPLOAD  — an image the customer supplied. Badged "Your image".
 16	 *   3. neither — the product's own hosting artwork, badged "Placeholder", with
 17	 *      the reason no capture exists ("not captured yet" / the actual failure).
 18	 *
 19	 * A stock photograph of some other website passed off as this one is precisely
 20	 * the shape this tree deleted once already. If a capture failed because the
 21	 * domain does not resolve, the card says that — which is information the
 22	 * customer needs and a prettier picture is not.
 23	 *
 24	 * `nx-dark-island`: the frame draws a photograph or the dark product plate under
 25	 * its own overlays in BOTH themes. Without the island, light mode flips the
 26	 * caption tokens to dark ink over a dark image. Same mechanism WhatsNewView's
 27	 * GameCoverTile caption uses.
 28	 */
 29	
 30	const PLACEHOLDER = "/nx/preview/hosting.webp";
 31	
 32	type Size = "hero" | "card" | "tile";
 33	
 34	const FRAME: Record<Size, string> = {
 35	  hero: "aspect-[16/10] rounded-[16px]",
 36	  card: "aspect-[16/10] rounded-[12px]",
 37	  tile: "aspect-[16/10] rounded-[10px]",
 38	};
 39	
 40	function badgeFor(thumb: SiteThumbView | null): { label: string; ink: string; icon: string } {
 41	  if (!thumb || thumb.status !== "READY") return { label: "Placeholder", ink: "text-slate-300", icon: "cloud" };
 42	  if (thumb.source === "UPLOAD") return { label: "Your image", ink: "text-violet-200", icon: "upload" };
 43	  return { label: "Live capture", ink: "text-emerald-200", icon: "eye" };
 44	}
 45	
 46	export function SitePreview({
 47	  accountId,
 48	  siteKey,
 49	  hostname,
 50	  thumb,
 51	  size = "card",
 52	  canCapture,
 53	  onChanged,
 54	  /** Hide the capture/upload controls — used where the frame is decorative. */
 55	  readOnly,
 56	}: {
 57	  accountId: string;
 58	  siteKey: string;
 59	  hostname: string;
 60	  thumb: SiteThumbView | null;
 61	  size?: Size;
 62	  /** False while the site isn't serving yet: a capture would photograph an error
 63	   *  page, so the control says why instead of producing one. */
 64	  canCapture: boolean;
 65	  onChanged?: () => void;
 66	  readOnly?: boolean;
 67	}) {
 68	  const [busy, start] = useTransition();
 69	  const [error, setError] = useState<string | null>(null);
 70	  const [uploading, setUploading] = useState(false);
 71	  const fileRef = useRef<HTMLInputElement | null>(null);
 72	
 73	  const ready = thumb?.status === "READY" && thumb.url;
 74	  const pending = thumb?.status === "PENDING";
 75	  const badge = badgeFor(thumb ?? null);
 76	
 77	  function capture() {
 78	    setError(null);
 79	    start(async () => {
 80	      const r = await captureSiteThumb(accountId, siteKey);
 81	      if (r.error) setError(r.error);
 82	      else onChanged?.();
 83	    });
 84	  }
 85	
 86	  function clear() {
 87	    setError(null);
 88	    start(async () => {
 89	      const r = await clearSiteThumb(accountId, siteKey);
 90	      if (r.error) setError(r.error);
 91	      else onChanged?.();
 92	    });
 93	  }
 94	
 95	  async function upload(file: File) {
 96	    setError(null);
 97	    setUploading(true);
 98	    try {
 99	      const fd = new FormData();
100	      fd.set("file", file);
101	      const res = await fetch(
102	        `/api/hosting/thumb?accountId=${encodeURIComponent(accountId)}&siteKey=${encodeURIComponent(siteKey)}`,
103	        { method: "POST", body: fd },
104	      );
105	      if (!res.ok) {
106	        const j = (await res.json().catch(() => ({}))) as { error?: string };
107	        setError(j.error ?? "That image couldn’t be saved.");
108	        return;
109	      }
110	      onChanged?.();
111	    } catch {
112	      setError("The upload didn’t reach us.");
113	    } finally {
114	      setUploading(false);
115	    }
116	  }
117	
118	  return (
119	    <div className="flex min-w-0 flex-col gap-2">
120	      <div className={`nx-dark-island relative overflow-hidden border border-rim-hi bg-[#04101f] ${FRAME[size]}`}>
121	        {/* eslint-disable-next-line @next/next/no-img-element -- a stored capture
122	            and a local plate, both outside the image optimizer */}
123	        <img
124	          src={ready ? thumb!.url! : PLACEHOLDER}
125	          alt={ready ? `Screenshot of ${thumb!.hostname}` : ""}
126	          className={
127	            "h-full w-full object-cover object-top transition-transform duration-500 " +
128	            (ready ? "" : "opacity-[0.55] object-center")
129	          }
130	        />
131	
132	        {/* A floor so the caption strip always has something to sit on, whatever
133	            the picture's own bottom edge happens to be. */}
134	        <span
135	          aria-hidden
136	          className="pointer-events-none absolute inset-x-0 bottom-0 h-2/5"
137	          style={{ background: "linear-gradient(180deg, transparent, rgba(3,10,24,.92))" }}
138	        />
139	
140	        {/* Which of the three sources this is. Always present. */}
141	        <span className="absolute left-2 top-2 inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-black/55 px-2 py-0.5 text-[10px] font-bold backdrop-blur-sm">
142	          <Icon name={badge.icon} size={10} tone="inherit" className={badge.ink} />
143	          <span className={badge.ink}>{badge.label}</span>
144	        </span>
145	
146	        {pending && (
147	          <span className="absolute right-2 top-2 inline-flex items-center gap-1.5 rounded-full border border-sky-400/40 bg-black/55 px-2 py-0.5 text-[10px] font-bold text-sky-200 backdrop-blur-sm">
148	            <Icon name="refresh2" size={10} tone="inherit" className="nx-spin" />
149	            Capturing
150	          </span>
151	        )}
152	
153	        {thumb?.stale && ready && (
154	          <span className="absolute right-2 top-2 rounded-full border border-amber-400/40 bg-black/55 px-2 py-0.5 text-[10px] font-bold text-amber-200 backdrop-blur-sm">
155	            Taken of {thumb.hostname}
156	          </span>
157	        )}
158	
159	        <div className="absolute inset-x-0 bottom-0 flex items-end justify-between gap-2 px-2.5 pb-2">
160	          <span className="min-w-0 truncate text-[11.5px] font-bold text-white drop-shadow">{hostname}</span>
161	          {!readOnly && (
162	            <span className="flex flex-none items-center gap-1">
163	              <button
164	                type="button"
165	                disabled={busy || uploading || !canCapture || pending}
166	                title={
167	                  canCapture
168	                    ? "Take a fresh screenshot of this site"
169	                    : "We can photograph this site once it’s answering on its domain"
170	                }
171	                onClick={capture}
172	                className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-[#8b5cff]/60 disabled:opacity-35"
173	              >
174	                <Icon name={pending ? "refresh2" : "eye"} size={12} tone="inherit" className={pending ? "nx-spin" : ""} />
175	              </button>
176	              <button
177	                type="button"
178	                disabled={busy || uploading}
179	                title="Upload your own image instead"
180	                onClick={() => fileRef.current?.click()}
181	                className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-[#8b5cff]/60 disabled:opacity-35"
182	              >
183	                <Icon name={uploading ? "refresh2" : "upload"} size={12} tone="inherit" className={uploading ? "nx-spin" : ""} />
184	              </button>
185	              {thumb && (
186	                <button
187	                  type="button"
188	                  disabled={busy || uploading}
189	                  title="Remove this picture and fall back to the placeholder"
190	                  onClick={clear}
191	                  className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-rose-400/60 disabled:opacity-35"
192	                >
193	                  <Icon name="trash" size={12} tone="inherit" />
194	                </button>
195	              )}
196	            </span>
197	          )}
198	        </div>
199	      </div>
200	
201	      <input
202	        ref={fileRef}
203	        type="file"
204	        accept="image/png,image/jpeg,image/gif,image/webp"
205	        className="hidden"
206	        onChange={(e) => {
207	          const f = e.target.files?.[0];
208	          e.currentTarget.value = "";
209	          if (f) void upload(f);
210	        }}
211	      />
212	
213	      {/* Why there is no real picture, when there is no real picture. */}
214	      {!readOnly && (
215	        <p className="text-[10.5px] leading-relaxed text-tx-faint">
216	          {error ? (
217	            <span className="text-rose-300">{error}</span>
218	          ) : thumb?.status === "FAILED" ? (
219	            <span className="text-amber-300">Preview not captured — {thumb.error}</span>
220	          ) : pending ? (
221	            "Taking a screenshot of your homepage…"
222	          ) : ready ? (
223	            thumb!.source === "UPLOAD"
224	              ? "Your own image. Re-capture any time to use a live screenshot instead."
225	              : `Captured ${thumb!.capturedAt ? new Date(thumb!.capturedAt).toLocaleString() : ""}.`
226	          ) : canCapture ? (
227	            "No screenshot yet — capture one, or upload your own image."
228	          ) : (
229	            "We’ll photograph your homepage once the site is answering on its domain."
230	          )}
231	        </p>
232	      )}
233	    </div>
234	  );
235	}

 1	import { db } from "@/lib/db";
 2	import { currentUser, realUser } from "@/lib/auth";
 3	import { isStaff } from "@/lib/rbac";
 4	import { isAllowedImageMime } from "@/lib/chat-attachment";
 5	
 6	export const runtime = "nodejs";
 7	
 8	/**
 9	 * GET /api/services/preview/[serverId] — stream the card image a customer set
10	 * for one of their own services (/dashboard/services).
11	 *
12	 * Authorization is the owner or staff, nothing wider: a preview is a picture
13	 * the customer chose for their own dashboard, not public content. `serverId`
14	 * is a database id rather than a filename, so there is no path traversal, and
15	 * the response carries the same lockdown the chat-attachment route uses — the
16	 * real stored MIME (always allow-listed), `nosniff`, an inline disposition and
17	 * a `default-src 'none'` CSP, so it can never execute as a document.
18	 *
19	 * Cached `private` and keyed by the `?v=` stamp the page appends (the preview's
20	 * updatedAt), so replacing an image is visible immediately without making the
21	 * route itself uncacheable.
22	 */
23	export async function GET(
24	  _req: Request,
25	  { params }: { params: Promise<{ serverId: string }> }
26	) {
27	  const { serverId } = await params;
28	  if (typeof serverId !== "string" || !serverId) return new Response("Not found", { status: 404 });
29	
30	  const preview = await db.servicePreview.findUnique({
31	    where: { serverId },
32	    include: { server: { select: { userId: true } } },
33	  });
34	  if (!preview) return new Response("Not found", { status: 404 });
35	
36	  const staff = await realUser();
37	  let authorized = Boolean(staff && isStaff(staff.role));
38	  if (!authorized) {
39	    const user = await currentUser();
40	    authorized = Boolean(user && user.id === preview.server.userId);
41	  }
42	  if (!authorized) return new Response("Forbidden", { status: 403 });
43	
44	  // Defense in depth: never serve anything that isn't an allow-listed image.
45	  const mime = isAllowedImageMime(preview.mime) ? preview.mime : "application/octet-stream";
46	  const data: Buffer = Buffer.isBuffer(preview.bytes)
47	    ? preview.bytes
48	    : Buffer.from(preview.bytes as Uint8Array);
49	
50	  return new Response(new Uint8Array(data), {
51	    status: 200,
52	    headers: {
53	      "Content-Type": mime,
54	      "Content-Length": String(data.length),
55	      "Content-Disposition": 'inline; filename="preview"',
56	      "X-Content-Type-Options": "nosniff",
57	      "Content-Security-Policy": "default-src 'none'; sandbox",
58	      "Cache-Control": "private, max-age=31536000, immutable, no-transform",
59	    },
60	  });
61	}

  1	import { NextRequest, NextResponse } from "next/server";
  2	import { requireUser } from "@/lib/auth";
  3	import { db } from "@/lib/db";
  4	import { validateImageBytes } from "@/lib/chat-attachment";
  5	import { parseSiteKey, MAX_THUMB_BYTES } from "@/lib/hosting-sites";
  6	
  7	/**
  8	 * Website preview bytes.
  9	 *
 10	 * GET  — serve one stored preview (a capture or a customer upload). Owner or
 11	 *        admin only: a preview is a photograph of the customer's site as it
 12	 *        stands, which can include a staging page they have not published.
 13	 * POST  — replace one site's preview with an image the customer supplies.
 14	 * The bytes live on HostingSiteThumb in Postgres, the same convention
 15	 * ChatAttachment and SignatureImage use.
 16	 *
 17	 * Upload validation goes through the platform's existing image validator, which
 18	 * authenticates the bytes by SIGNATURE rather than the declared Content-Type and
 19	 * refuses SVG outright. There is no second allow-list here for the two to drift
 20	 * apart on.
 21	 */
 22	
 23	/** Owner-or-admin on the account that owns a thumb row. */
 24	async function ownedThumb(id: string) {
 25	  const user = await requireUser();
 26	  const row = await db.hostingSiteThumb.findUnique({
 27	    where: { id },
 28	    select: { id: true, mime: true, data: true, status: true, account: { select: { userId: true } } },
 29	  });
 30	  if (!row) return null;
 31	  if (row.account.userId !== user.id && user.role !== "ADMIN") return null;
 32	  return row;
 33	}
 34	
 35	export async function GET(req: NextRequest) {
 36	  const id = req.nextUrl.searchParams.get("id") ?? "";
 37	  if (!id) return new NextResponse("Not found", { status: 404 });
 38	  const row = await ownedThumb(id).catch(() => null);
 39	  if (!row || row.status !== "READY" || !row.data || !row.mime) {
 40	    return new NextResponse("Not found", { status: 404 });
 41	  }
 42	  return new NextResponse(new Uint8Array(row.data), {
 43	    status: 200,
 44	    headers: {
 45	      "Content-Type": row.mime,
 46	      // Private: this is the customer's own site, possibly unpublished. The URL
 47	      // already carries an updatedAt cache-buster, so a long browser cache is
 48	      // safe and a replacement is picked up immediately.
 49	      "Cache-Control": "private, max-age=86400",
 50	      "Content-Disposition": "inline",
 51	    },
 52	  });
 53	}
 54	
 55	export async function POST(req: NextRequest) {
 56	  const user = await requireUser().catch(() => null);
 57	  if (!user) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
 58	
 59	  const accountId = req.nextUrl.searchParams.get("accountId") ?? "";
 60	  const siteKey = req.nextUrl.searchParams.get("siteKey") ?? "";
 61	  if (!parseSiteKey(siteKey)) return NextResponse.json({ error: "Unknown website." }, { status: 400 });
 62	
 63	  const account = await db.hostingAccount.findUnique({
 64	    where: { id: accountId },
 65	    select: { id: true, userId: true, primaryDomain: true },
 66	  });
 67	  if (!account) return NextResponse.json({ error: "Not found" }, { status: 404 });
 68	  if (account.userId !== user.id && user.role !== "ADMIN") {
 69	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
 70	  }
 71	
 72	  // Resolve the site key to the hostname this picture is FOR, so a later rename
 73	  // can be detected and the picture flagged stale rather than shown as current.
 74	  const parsed = parseSiteKey(siteKey)!;
 75	  let hostname = account.primaryDomain;
 76	  if (parsed.kind === "subdomain") {
 77	    const s = await db.hostingSubdomain.findFirst({ where: { id: parsed.id, accountId }, select: { fqdn: true } });
 78	    if (!s) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
 79	    hostname = s.fqdn;
 80	  } else if (parsed.kind === "addon") {
 81	    const d = await db.hostingAddonDomain.findFirst({ where: { id: parsed.id, accountId }, select: { domain: true } });
 82	    if (!d) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
 83	    hostname = d.domain;
 84	  }
 85	
 86	  const form = await req.formData();
 87	  const file = form.get("file");
 88	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
 89	  if (file.size > MAX_THUMB_BYTES) {
 90	    return NextResponse.json({ error: "Image is larger than 4 MB." }, { status: 413 });
 91	  }
 92	
 93	  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type || null);
 94	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
 95	
 96	  await db.hostingSiteThumb.upsert({
 97	    where: { accountId_siteKey: { accountId, siteKey } },
 98	    create: {
 99	      accountId, siteKey, hostname, source: "UPLOAD", status: "READY",
100	      mime: check.mime, sizeBytes: check.bytes.length, data: new Uint8Array(check.bytes),
101	      error: null, capturedAt: new Date(),
102	    },
103	    update: {
104	      hostname, source: "UPLOAD", status: "READY",
105	      mime: check.mime, sizeBytes: check.bytes.length, data: new Uint8Array(check.bytes),
106	      error: null, capturedAt: new Date(), width: null, height: null,
107	    },
108	  });
109	
110	  return NextResponse.json({ ok: true });
111	}

