102	/** Tolerant status mapper: every product spells its states differently, and a
103	 *  new value should degrade to something sane rather than crash a list. */
104	function normalizeStatus(raw: string): { status: ServiceStatus; label: string } {
105	  const s = (raw ?? "").toUpperCase();
106	  if (["RUNNING", "ACTIVE", "ONLINE"].includes(s)) return { status: "running", label: "Running" };
107	  // The free tier's container states: READY means the container exists —
108	  // mc-router owns whether it is awake right now, and this list deliberately
109	  // doesn't claim to know that, so it says Ready rather than Running.
110	  if (s === "READY") return { status: "running", label: "Ready" };
111	  if (["PENDING", "PROVISIONING", "CREATING", "REINSTALLING", "STARTING"].includes(s)) {
112	    return { status: "pending", label: s === "REINSTALLING" ? "Reinstalling" : "Pending" };
113	  }
114	  if (["STOPPED", "SLEEPING", "OFFLINE"].includes(s)) {
115	    return { status: "stopped", label: s === "SLEEPING" ? "Asleep" : "Stopped" };
116	  }
117	  if (["SUSPENDED"].includes(s)) return { status: "suspended", label: "Suspended" };
118	  // Domain-only inbound-transfer states (DomainStatus) — without these two, the
119	  // fallback below stringifies "TRANSFER_PENDING" into "Transfer_pending".
120	  if (s === "TRANSFER_PENDING") return { status: "pending", label: "Transferring" };
121	  if (s === "TRANSFER_FAILED") return { status: "error", label: "Transfer failed" };
122	  if (["DELETING", "DELETED", "CANCELLED", "CANCELED", "TERMINATED", "EXPIRED"].includes(s)) {
123	    return { status: "cancelled", label: s === "DELETING" ? "Deleting" : "Cancelled" };
124	  }
125	  if (["ERROR", "FAILED"].includes(s)) return { status: "error", label: "Failed" };
126	  return { status: "pending", label: raw ? raw.charAt(0) + raw.slice(1).toLowerCase() : "Unknown" };
127	}
