138	/** Stock plates, for a service with nothing of its own to show yet. */
139	const STOCK_PREVIEW = {
140	  vps: "/nx/preview/vps.webp",
141	  hosting: "/nx/preview/hosting.webp",
142	  // Neither product has its own wide 16:4 rack plate yet — domains reuse the
143	  // real hero art from /dashboard/domains rather than a stretched icon; email
144	  // has no dedicated wide art at all, so it falls back to its own service mark.
145	  domain: "/nx/hero-domains-globe.webp",
146	  email: "/nx/svc/email.webp",
147	} as const;
