149	/** Landscape key art for a game family, which every family in the catalogue has. */
150	function gameHeroArt(family: string | null): string | null {
151	  const slug = family ? GAME_ART_SLUG[family as GameFamily]?.hero : null;
152	  return slug ? `/games/art/${slug}_hero.jpg` : null;
153	}
