155	/**
156	 * Where a Server row's card image comes from, in priority order: the image the
157	 * customer set, then the game's own key art, then the stock rack plate. The
158	 * `v` stamp is the preview's updatedAt, so replacing an image busts the cache
159	 * without making the route itself uncacheable.
160	 */
161	function serverPreview(
162	  id: string, isGame: boolean, family: string | null, previewStamp: Date | null,
163	): Pick<ServiceRow, "previewSrc" | "previewSource" | "siteToFrame" | "canSetPreview"> {
164	  if (previewStamp) {
165	    return {
166	      previewSrc: `/api/services/preview/${id}?v=${previewStamp.getTime()}`,
167	      previewSource: "customer",
168	      siteToFrame: null,
169	      canSetPreview: true,
170	    };
171	  }
172	  const art = isGame ? gameHeroArt(family) : null;
173	  return {
174	    previewSrc: art ?? STOCK_PREVIEW.vps,
175	    previewSource: art ? "game-art" : "stock",
176	    siteToFrame: null,
177	    // Game servers lead with their own key art, which is better than anything a
178	    // customer would upload — the swap is offered on VPS rows only.
179	    canSetPreview: !isGame,
180	  };
181	}
